library(dplyr)
library(ggplot2)
library(purrr)
library(patchwork)

# ======================================================================================
# 02 - ANALYSIS OF DIFFERENTIALLY SPLICED EVENTS
# ======================================================================================
# Input:
#   - dPSI tables generated by 01_Filtering_AS_events.R
#
# Analysis:
#   - Classify AS events by type (Exon, Intron, Alt5, Alt3)
#   - Identify differential splicing events using abs(dPSI) > 10
#   - Quantify differentially spliced events per condition and event type
#   - Calculate Pearson correlations of dPSI values between AM007 and AM016
#   - Generate correlation plots for all events and individual event types
#   - Export differentially spliced events separately for each cell line
#
# Output:
#   - Barplot of differential splicing events by event type (SVG)
#   - Correlation plots comparing dPSI between AM007 and AM016 (SVG)
#   - Differentially spliced event tables per condition (Excel and RDS)
#
# Dependencies:
#   - 01_Filtering_AS_events.R (input data)
#   - 00_utils.R
#   - dplyr, ggplot2, purrr, patchwork and additional packages managed through renv
#
# ======================================================================================

# paths & directories
root_dir <- ""
files_dir <- file.path(root_dir,"AS", "Files")
graphs_dir <- file.path(root_dir,"AS", "Graphs")

# functions/utils
source(file.path(root_dir,"00_utils.R"))


# dPSI values
dPSI <- read.table(file.path(files_dir,"dPSI_values_AMcelllines_sgSF3B4_n356613.txt"), sep="\t", header=TRUE)
dPSI_annot <- read.table(file.path(files_dir,"IncTable_dPSI_values_AMcelllines_sgSF3B4_n356613.txt"), sep="\t", header=TRUE)


# colors per event type
colors_per_event_type <- c("Alt3" = "#ef476f",  
                     "Alt5" = "#ffd166",  
                     "Exon" = "#118ab2", 
                   "Intron" = "#06d6a0") 

# params
dataset <- "AM_sgSF3B4"   # just for file names
dPSI_threshold <- 10 # dPSI threshold to consider diff spliced events


# ======================================================================================
# Check number of diff spliced events
# =======================================================================================

# Add EVENT_TYPE column based on regex patterns in EVENT column
dPSI <- dPSI %>%
  mutate(EVENT_TYPE = case_when(
    grepl("^HsaEX\\d+", EVENT) ~ "Exon",
    grepl("^HsaINT\\d+", EVENT) ~ "Intron",
    grepl("^HsaALTD\\d+", EVENT) ~ "Alt5",
    grepl("^HsaALTA\\d+", EVENT) ~ "Alt3"
  )) %>%
  select(EVENT, EVENT_TYPE, everything())

num_cols <- names(dPSI)[3:ncol(dPSI)]


# Barplot diff spliced events per event type
plot_diff_spliced_events_barplot(
  dPSI_data             = dPSI, 
  num_cols              = num_cols,
  dPSI_threshold        = dPSI_threshold,
  colors_per_event_type = colors_per_event_type,
  label_size            = 3, 
  svg_height            = 6,
  svg_width             = 5,
  output_dir            = graphs_dir,
  output_svg            = paste0("BarPlot_DiffEvents_",dataset,"dPSI", dPSI_threshold, "_perEventType.svg") 
)


# ======================================================================================
# Correlation of splicing changes between conditions (per event type)
# =======================================================================================

x_col <- "dPSI_AM007"
y_col <- "dPSI_AM016"

plot_data <- dPSI %>%
  filter(
    !is.na(.data[[x_col]]),
    !is.na(.data[[y_col]])
  )

axis_limits <- c(-100,100)


event_types <- unique(plot_data$EVENT_TYPE)

plots <- c(
  list(make_cor_plot(plot_data, "All events", x_col, y_col, axis_limits)),
  purrr::map(
    event_types,
    ~ make_cor_plot(
      dplyr::filter(plot_data, EVENT_TYPE == .x),
      .x,
      x_col,
      y_col,
      axis_limits
    )
  )
)

correlation_panel <- wrap_plots(
  plots,
  ncol = 3,
  nrow = 2
)

ggsave(
  filename = file.path(graphs_dir,"CorrPlots_dPSI_sgSF3B4_betweenAMCellLines_perEventType.svg"),
  plot = correlation_panel,
  width = 8,
  height = 5.5,
  units = "in"
)


# ======================================================================================
# Save data in different formats
# ======================================================================================
diff_events <- save_data_diff_events(
  dPSI_data         = dPSI_annot,
  start_col         = 7,
  dPSI_threshold    = dPSI_threshold,
  output_dir        = files_dir, 
  excel_filename    = paste0("dPSI_DiffEvents_",dataset,"_dPSI", dPSI_threshold, "_percondition.xlsx"),
  r_object_filename = paste0("dPSI_DiffEvents_",dataset,"_dPSI", dPSI_threshold, "_percondition.RData")
)


